'use strict';

// MAIN //

/**
* Tests whether two 64-bit unsigned integers are equal using word comparison.
*
* @param {uinteger} ah - high 32-bit word of the first 64-bit unsigned integer
* @param {uinteger} al - low 32-bit word of the first 64-bit unsigned integer
* @param {uinteger} bh - high 32-bit word of the second 64-bit unsigned integer
* @param {uinteger} bl - low 32-bit word of the second 64-bit unsigned integer
* @returns {boolean} boolean indicating if both 64-bit unsigned integers are equal
*
* @example
* var bool = words( 0, 5, 0, 5 );
* // returns true
*
* bool = words( 0, 5, 0, 10 );
* // returns false
*/
function words( ah, al, bh, bl ) {
	return ( ( ( ah ^ bh ) | ( al ^ bl ) ) === 0 );
}


// EXPORTS //

module.exports = words;
